# -*- coding: utf-8 -*-
"""mascot 贴图 · base64 内嵌数据

用途：部分 skill 分发平台禁止上传 PNG 等二进制文件，
贴图因此以纯文本（base64）形式内嵌在本文件中，运行时解码使用，
效果与 assets/stickers/*.png 完全一致。

规格：448x448，256 色量化（原图 1024x1024 RGB，卡通形象色块少，视觉无损）。
生成方式见 SKILL.md「贴图与分发」一节，勿手工编辑。
"""
import base64, io
from PIL import Image

_SIZE = 448
_DATA = {
    '暗夜造梦师': '',
    '温暖治愈系': '',
    '智性探索者': '',
    '情感深渊潜行者': '',
    '冒险浪漫派': '',
    '世界观建筑师': '',
    '纯粹感受者': '',
    '暗黑实验家': '',
    '现实凝视者': '',
    '复杂共情者': '',
    '热忱群像派': '',
    '多元观影者': '',
}


def load(name):
    """按人格名返回 mascot 的 RGBA 图；无数据则返回 None。"""
    b = _DATA.get(name)
    if not b:
        return None
    return Image.open(io.BytesIO(base64.b64decode(b))).convert("RGBA")
